public class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    /**
     * No-argument constructor.
     */
    public LogPurgeJob() {
    }

    /**
     * Implementation of Schedulable interface.
     * Starts the batch job to perform the purge.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeJob());
    }

    /**
     * Implementation of Database.Batchable interface.
     * Defines the scope of records to be purged using a QueryLocator for bulk-safety.
     */
    public Database<sObject> start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneEightyDaysAgo = DateTime.now().addDays(-180);

        // Logic:
        // - If Level__c is not 'ERROR' (including null/blank), delete if older than 30 days.
        // - If Level__c is 'ERROR', delete if older than 180 days.
        return Database.getQueryLocator([
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE ((Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :thirtyDaysAgo)
               OR (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
        ]);
    }

    /**
     * Implementation of Database.Batchable interface.
     * Deletes the records identified in the current batch.
     */
    public void execute(Database.BatchableContext bc, List<sObject> scope) {
        if (scope != null && !scope.isEmpty()) {
            delete scope;
        }
    }

    /**
     * Implementation of Database.Batchable interface.
     */
    public void finish(Database.BatchableContext bc) {
        // No additional actions required after the batch completes.
    }

    /**
     * Schedules the job to run every day at 02:00.
     * 
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
