public class ContactPhoneCleanup {

    /**
     * Normalizes phone numbers for a list of Contact IDs.
     * Removes all characters except digits and the '+' sign.
     *
     * @param contactIds List of Contact IDs to process.
     * @return A Map where the key is the Contact ID and the value is the first error message if the update failed.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorMap = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorMap;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // Query contacts to get their current phone numbers.
        for (Contact con : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds]) {
            if (String.isNotBlank(con.Phone)) {
                // Remove every character that is not a digit or '+'
                // Regex explanation: [^\\d+] matches any character that is NOT a digit (\\d) or a '+' sign.
                con.Phone = con.Phone.replaceAll('[^\\d+]', '');
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // Perform partial success update to ensure one failure doesn't block others.
            Database.SaveResult[] results = Database.update(contactsToUpdate, false);

            for (Integer i = 0; i < results.size(); i++) {
                Database.SaveResult sr = results[i];
                if (!sr.isSuccess()) {
                    // Map the Id of the contact that failed to its first error message.
                    errorMap.put(contactsToUpdate[i].Id, sr.getErrors()[0].getMessage());
                }
            }
        }

        return errorMap;
    }
}
