public class FollowUpTaskService {

    /**
     * Creates follow-up tasks for a given list of Opportunity IDs.
     * 
     * @param opportunityIds A list of IDs representing the opportunities to process.
     * @return A set of Opportunity IDs for which task creation failed.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // 1. Bulk query opportunities to avoid SOQL in loops.
        // This is more efficient and avoids hitting governor limits.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId 
            FROM Opportunity 
            WHERE Id IN :opportunityIds
        ];

        if (opportunities.isEmpty()) {
            return failedOpportunityIds;
        }

        // 2. Prepare the list of tasks to be inserted in bulk.
        List<Task> tasksToInsert = new List<Task>();

        // We need to maintain a mapping from the Task index to the original Opportunity ID
        // to identify which one failed in the Database.SaveResult collection.
        List<Id> taskToOppIdMapping = new List<Id>();

        for (Opportunity opp : opportunities) {
            Task t = new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            );
            tasksToInsert.add(t);
            taskToOppIdMapping.add(opp.Id);
        }

        // 3. Perform bulk insertion with partial success enabled.
        // Database.insert(tasks, false) allows successful records to be committed
        // even if some records fail due to validation rules or other errors.
        // This satisfies the requirement that a rejected task must not stop others.
        Database.SaveResult[] results = Database.insert(tasksToInsert, false);

        // 4. Identify which opportunities had task creation failures.
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(taskToOppIdMapping[i]);
            }
        }

        return failedOpportunityIds;
    }
}
