public with sharing class AccountCountrySync {
    /**
     * Synchronizes Contact MailingCountry with Account BillingCountry when the latter changes.
     *
     * @param newList The list of new Account records from the trigger.
     * @param oldMap The map of old Account records from the trigger.
     */
    public static void syncContactCountry(List<Account> newList, Map<Id, Account> oldMap) {
        Set<Id> accountIdsToProcess = new Set<Id>();
        Map<Id, String> accountIdToOldCountry = new Map<Id, String>();
        Map<Id, String> accountIdToNewCountry = new Map<Id, String>();

        // Identify accounts where BillingCountry has changed
        for (Account acc : newList) {
            Account oldAcc = oldMap.get(acc.Id);
            // Detect changes including null to non-null or vice versa
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                accountIdsToProcess.add(acc.Id);
                accountIdToOldCountry.put(acc.Id, oldAcc.BillingCountry);
                accountIdToNewCountry.put(acc.Id, acc.BillingCountry);
            }
        }

        // If no accounts had a country change, exit early
        if (accountIdsToProcess.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // Query only the contacts associated with the accounts that changed.
        // This is the correct, bulk-safe approach for a large org.
        for (Contact con : [SELECT Id, AccountId, MailingCountry 
                            FROM Contact 
                            WHERE AccountId IN :accountIdsToProcess]) {

            String oldCountry = accountIdToOldCountry.get(con.AccountId);
            String newCountry = accountIdToNewCountry.get(con.AccountId);

            // Requirement: Update if MailingCountry is blank or matches the previous BillingCountry
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // Perform DML in bulk
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
