import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    _options = [];
    @api get options() {
        return this._options;
    }
    set options(value) {
        this._options = value || [];
        this._updateActiveIndexFromValue();
    }

    _value;
    @api get value() {
        return this._value;
    }
    set value(val) {
        if (this._value !== val) {
            this._value = val;
            this._updateActiveIndexFromValue();
        }
    }

    activeOptionIndex = 0;

    _updateActiveIndexFromValue() {
        if (!this._options || this._options.length === 0) {
            this.activeOptionIndex = 0;
            return;
        }
        const foundIndex = this._options.findIndex(opt => opt.value === this._value);
        if (foundIndex !== -1) {
            this.activeOptionIndex = foundIndex;
        } else {
            this.activeOptionIndex = 0;
        }
    }

    get optionsWithIds() {
        return this._options.map((opt, index) => ({
            ...opt,
            id: `opt-${index}`,
            isSelected: opt.value === this._value
        }));
    }

    get activeOptionId() {
        const len = this._options.length;
        if (len > 0 && this.activeOptionIndex >= 0 && this.activeOptionIndex < len) {
            return `opt-${this.activeOptionIndex}`;
        }
        return '';
    }

    handleKeyDown(event) {
        const { key } = event;
        const len = this._options.length;
        if (len === 0) return;

        let moved = false;

        if (key === 'ArrowDown') {
            if (this.activeOptionIndex < len - 1) {
                this.activeOptionIndex++;
                moved = true;
            }
        } else if (key === 'ArrowUp') {
            if (this.activeOptionIndex > 0) {
                this.activeOptionIndex--;
                moved = true;
            }
        } else if (key === 'Home') {
            this.activeOptionIndex = 0;
            moved = true;
        } else if (key === 'End') {
            this.activeOptionIndex = len - 1;
            moved = true;
        } else if (key === 'Enter' || key === ' ') {
            const selectedValue = this._options[this.activeOptionIndex]?.value;
            this.selectValue(selectedValue);
            moved = true;
        }

        if (moved) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const val = event.currentTarget.dataset.value;
        const idx = this._options.findIndex(opt => String(opt.value) === val);
        if (idx !== -1) {
            this.activeOptionIndex = idx;
            this.selectValue(this._options[idx].value);
        }
    }

    selectValue(val) {
        if (val !== this._value) {
            this._value = val;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: val }
            }));
        }
    }
}
