public class FamilyService {
    /**
     * Links parents to children in NPSP based on the provided map.
     * 
     * @param parentIdByChildId A map where keys are child Contact IDs and values are parent Contact IDs.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allContactIds = new Set<Id>();
        for (Map.Entry<Id, Id> entry : parentIdByChildId.entrySet()) {
            if (entry.getKey() != null) {
                allContactIds.add(entry.getKey());
            }
            if (entry.getValue() != null) {
                allContactIds.add(entry.getValue());
            }
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // To skip pairs where any relationship already exists (in either direction),
        // we first find all existing relationships involving the contacts in our set.
        // We use a set of string keys "id1-id2" where id1 < id2 to uniquely identify pairs.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c 
            FROM npe4__Relationship__c 
            WHERE npe4__Contact__c IN :allContactIds 
            OR npe4__RelatedContact__c IN :allContactIds
        ]) {
            Id id1 = rel.npe4__Contact__c;
            Id id2 = rel.npe4__RelatedContact__c;
            if (id1 != null && id2 != null) {
                existingPairs.add(id1 < id2 ? id1 + '-' + id2 : id2 + '-' + id1);
            }
        }

        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();
        // Track pairs added in this batch to prevent duplicates if the map contains both (Child, Parent) and (Parent, Child).
        Set<String> addedInBatch = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            // Create a unique key for the pair regardless of direction.
            String pairKey = childId < parentId ? childId + '-' + parentId : parentId + '-' + childId;

            // If a relationship already exists in the database or we have already decided to add it in this batch, skip.
            if (!existingPairs.contains(pairKey) && !addedInBatch.contains(pairKey)) {
                newRelationships.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                ));
                addedInBatch.add(pairKey);
            }
        }

        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }
}
